(* [comment removed for export] *)
Definition ram_frame (junk : list byte) (s4 s3 s2 s1 s0 ra : word) : list cell :=
  [CB 8 junk; C8 (wz canary_val); C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

